<script setup lang="ts">
import {computed,onMounted,ref,shallowRef} from 'vue';
import {unifiedWorkspace,unifiedKnowledge,unifiedLearning} from '../services';
import type {Output} from '../../shared/protocol/registry';
import type {DateSelectionInput} from '../../shared/workspace-contracts';
import DateRangeControl from '../components/DateRangeControl.vue';
import ReviewLineChart from '../components/ReviewLineChart.vue';
const props=defineProps<{deckId:string;overview?:boolean}>(),emit=defineEmits<{view:[cardId:string,eventId:string]}>();
const date=ref<DateSelectionInput>({range:'30'}),result=shallowRef<Output<'workspace.analytics'>>(),rows=ref<Output<'workspace.analytics'>['items']>([]),error=ref(''),busy=ref(false),tree=shallowRef<Output<'knowledge.tree.read'>>(),mastery=shallowRef<Output<'learning.mastery.deck'>>(),knowledgeRows=ref<{nodeId:string;name:string;value:Output<'learning.mastery.knowledge'>}[]>([]),knowledgeBusy=ref(false);
const statusNames:Record<string,string>={pending:'待评估',unseen:'尚未复盘',stale:'需要回顾',improving:'正在改善',insufficient:'证据不足',weak:'建议加强',suspected_weak:'有待巩固',stable:'持续掌握',unstable:'掌握波动'};
const records=computed(()=>[...rows.value].reverse().map((r,i)=>({id:r.eventId,ordinal:i+1,createdAt:r.createdAt,selfScore:r.scoreTenths===null?null:r.scoreTenths/10,elapsedSeconds:r.elapsedSeconds,correct:r.objectiveCorrect,effective:true})));
async function load(more=false){busy.value=true;error.value='';try{const r=await unifiedWorkspace.analytics({deckId:props.deckId,date:date.value,cursor:more?result.value?.nextCursor:null});rows.value=more?[...rows.value,...r.items]:r.items;result.value=r;}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function knowledge(){if(knowledgeBusy.value)return;knowledgeBusy.value=true;try{tree.value??=await unifiedKnowledge.tree({deckId:props.deckId});const next=tree.value.nodes.slice(knowledgeRows.value.length,knowledgeRows.value.length+12);for(let i=0;i<next.length;i+=4){const values=await Promise.all(next.slice(i,i+4).map(async n=>({nodeId:n.nodeId,name:n.name,value:await unifiedLearning.knowledgeMastery({deckId:props.deckId,nodeId:n.nodeId,scope:'aggregate'})})));knowledgeRows.value.push(...values);}}catch(e){error.value=String(e);}finally{knowledgeBusy.value=false;}}
async function assess(){busy.value=true;try{mastery.value=await unifiedLearning.deckMastery({deckId:props.deckId});}catch(e){error.value=String(e);}finally{busy.value=false;}}
onMounted(()=>load());
</script>
<template><section aria-label="学习分析" class="unified-analytics">
 <div class="page-heading"><div><h1>学习分析</h1><p>从每一次复盘中，发现理解与记忆的变化。</p></div></div>
 <fieldset class="analytics-filter" :disabled="busy"><legend>统计范围</legend><DateRangeControl v-model="date"/><button @click="load()">更新分析</button></fieldset><p v-if="error" role="alert">{{error}}</p>
 <template v-if="result"><div class="summary-strip"><article class="metric"><div class="metric-label">范围内复盘</div><div class="metric-number">{{result.eventCount}} <small>次</small></div><span class="tiny-meta">其中仅练习 {{result.practiceCount}} 次</span></article><article class="metric"><div class="metric-label">当前掌握度</div><div class="metric-number mastery-status">{{mastery?statusNames[mastery.status]:'尚未评估'}}</div><span class="tiny-meta">当前周期 · {{mastery?.observations??0}} 次有效观察</span><button class="text-button" :disabled="busy" @click="assess">评估本集</button></article><article class="metric"><div class="metric-label">单选正确率</div><div class="metric-number">{{result.objectiveCount?Math.round(result.correctCount/result.objectiveCount*100)+'%':'未记录'}}</div><span class="tiny-meta">只统计有客观结果的复盘</span></article><article class="metric"><div class="metric-label">平均自评</div><div class="metric-number">{{result.averageScoreTenths===null?'未记录':(result.averageScoreTenths/10).toFixed(1)}} <small v-if="result.averageScoreTenths!==null">/ 10</small></div><span class="tiny-meta">平均用时 {{result.averageElapsedSeconds===null?'未记录':result.averageElapsedSeconds.toFixed(1)+' 秒'}}</span></article></div>
 <div class="analytics-charts"><section class="surface padded"><div class="section-heading"><h2>自评趋势</h2><span class="tiny-meta">点击回看当次复盘</span></div><ReviewLineChart :records="records" metric="selfScore" title="已加载记录 · 自评分" selected-id="" unified neutral @select="id=>{const r=rows.find(r=>r.eventId===id);if(r)emit('view',r.cardId,r.eventId)}"/></section><section class="surface padded"><div class="section-heading"><h2>用时趋势</h2><span class="tiny-meta">逐次复盘记录</span></div><ReviewLineChart :records="records" metric="elapsedSeconds" title="已加载记录 · 用时" selected-id="" unified neutral @select="id=>{const r=rows.find(r=>r.eventId===id);if(r)emit('view',r.cardId,r.eventId)}"/></section></div>
 <section class="surface padded knowledge-mastery" aria-label="知识点综合掌握度"><div class="section-heading"><h2>知识点掌握</h2><span class="tiny-meta">当前关联 · 按卡片去重</span></div><div v-for="r in knowledgeRows" :key="r.nodeId" class="mini-row"><span class="mini-row-main"><strong>{{r.name}}</strong><small>关联 {{r.value.cardIds.length}} 张卡片 · {{r.value.observations}} 次观察</small></span><span class="pill">{{statusNames[r.value.status]}}</span></div><div v-if="!knowledgeRows.length&&!knowledgeBusy" class="empty-state">{{tree?'还没有知识点，可在知识图谱中建立知识结构。':'按需读取知识点的当前掌握情况'}}</div><button v-if="!tree||knowledgeRows.length<tree.nodes.length" :disabled="knowledgeBusy" @click="knowledge">{{knowledgeBusy?'读取掌握度…':'更多知识点'}}</button></section>
 <section class="surface padded" aria-label="复盘记录列表"><div class="section-heading"><h2>最近复盘</h2><span class="tiny-meta">{{result.window.timeZone}} · {{result.cardCount}} 张当前卡片</span></div><button v-for="r in rows" :key="r.eventId" class="mini-row recent-link" :disabled="busy" @click="emit('view',r.cardId,r.eventId)"><span class="mini-row-main"><strong>{{r.title||'未命名卡片'}}</strong><small>{{new Date(r.createdAt).toLocaleString('zh-CN')}}</small></span><span class="pill">{{r.scoreTenths===null?'未记录':(r.scoreTenths/10).toFixed(1)+' 分'}}</span></button><div v-if="!rows.length" class="empty-state">此范围没有复盘记录。</div><button v-if="result.nextCursor" :disabled="busy" @click="load(true)">更多复盘记录</button></section>
 </template>
</section></template>
